#include <iostream>
#include <iomanip>
#include <cstdio>

int main() {
    // C-style printf width, precision, and dynamic asterisk (*)
    std::printf("%4d\n", 12);
    std::printf("%.4d\n", 873);
    std::printf("%9.3f\n", 123.456789);
    std::printf("%.11s\n", "Happy Birthday");

    int w = 7;
    int p = 2;
    std::printf("%*.*f\n", w, p, 98.736);

    // Equivalent modern C++17 stream formatting
    std::cout << std::setw(4) << 12 << "\n";
    std::cout << std::setfill('0') << std::setw(4) << 873 << "\n";
    std::cout << std::setfill(' ') << std::setw(9) << std::fixed << std::setprecision(3) << 123.456789 << "\n";
    return 0;
}

#include <iostream>
#include <iomanip>
#include <cstdio>

int main() {
    // Fig 9.11: Multi-type right and left justification
    std::printf("%10s%10d%10c%10f\n", "hello", 7, 'a', 1.23);
    std::printf("%-10s%-10d%-10c%-10f\n\n", "hello", 7, 'a', 1.23);

    // Fig 9.12 & 9.13: Plus flag and Space flag
    std::printf("%+d | %+d\n", 786, -786);
    std::printf("% d\n% d\n\n", 547, -547);

    // Flags # and 0 previewed in Fig 9.10 table
    std::printf("%#x | %#g | %05d\n", 0x593, 1427.0, 42);

    // Modern C++17 stream equivalent for alignment and signs
    std::cout << std::left << std::setw(10) << "hello"
              << std::setw(10) << 7 << "\n";
    std::cout << std::showpos << 786 << " | " << -786 << std::noshowpos << "\n";
    return 0;
}
